(function(){'use strict';
const A=CraftApp,M=CityAllocationMath,$=id=>document.getElementById(id),fmt=n=>Number(n||0).toLocaleString('ru-RU',{maximumFractionDigits:2}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allowed=x=>x.recipe.kind==='bags'||x.recipe.kind==='gear'&&x.recipe.blackMarket?[...M.cities,'Black Market']:M.cities;
const sales=document.createElement('section');sales.id='city-sales';sales.className='city-sales';sales.innerHTML='<label class="field">Распределение продажи<select id="city-sale-mode"><option value="single">Один город</option><option value="manual">По городам вручную</option><option value="demand">По объёму продаж</option></select></label><div id="city-demand-controls" hidden><label class="field">Размер партии<select id="city-demand-volume"><option value="batch">Распределить текущую партию</option><option value="market">Рассчитать по объёму рынка</option></select></label><div class="grid2"><label class="field">Срок продажи, дней<input id="city-demand-days" type="number" min="1" max="365" step="1"></label><label class="field">Доля оборота рынка, %<input id="city-demand-share" type="number" min="0.01" max="100" step="1"></label></div><fieldset id="city-demand-cities"><legend>Города продажи</legend></fieldset><p class="hint">Лимит города = средние продажи в день × срок × доля рынка. Сначала заполняются города с большей ценой. Нужна свежая история минимум за 3 дня. Глубина ордеров и конкуренция не известны; продажи не гарантированы.</p></div><div id="city-sales-plan"></div><button id="city-sales-edit" class="button" type="button" hidden>Изменить распределение</button>';
$('sale-status').after(sales);
const summary=document.createElement('details');summary.id='city-trade-summary';summary.className='city-trade-summary';summary.dataset.foldIgnore='';summary.innerHTML='<summary>Закупки и продажи по городам</summary><div></div>';$('stages').before(summary);
const dialog=document.createElement('dialog');dialog.id='city-allocation-dialog';dialog.className='city-allocation-dialog';dialog.setAttribute('aria-labelledby','city-allocation-title');document.body.append(dialog);let session=null;
function identity(){const x=A.snapshot();return JSON.stringify([Workspace.ticket(),x.recipe.id,x.config.quality,x.result.amount,x.result.bill.map(m=>[m.id,m.buy]),x.config.saleMode]);}
function close(){const focus=session?.focus;session=null;dialog.close();if(focus?.isConnected&&focus.checkVisibility())focus.focus({preventScroll:true});}
function rowsFromDialog(){return [...dialog.querySelectorAll('.city-allocation-row')].map(row=>({city:row.querySelector('select').value,quantity:row.querySelector('[data-part-quantity]').valueAsNumber,price:row.querySelector('[data-part-price]').value===''?null:row.querySelector('[data-part-price]').valueAsNumber}));}
function currentQuote(city){return session.kind==='sale'?A.allocationSaleQuote(city):A.allocationBuyQuote(session.id,city);}
function totals(){if(!session)return;const result=M.resolve(rowsFromDialog(),session.required,session.allowed,currentQuote);$('city-allocation-status').textContent='Распределено '+fmt(result.assigned)+' из '+fmt(session.required)+' шт. · '+fmt(result.total)+' серебра'+(result.valid?' · Всё распределено':'. '+result.errors.join(' '));$('city-allocation-status').classList.toggle('negative',!result.valid);return result;}
function append(row){const index=dialog.querySelectorAll('.city-allocation-row').length,node=document.createElement('div');node.className='city-allocation-row';node.innerHTML='<label class="field">Город<select aria-label="Город строки '+(index+1)+'">'+session.allowed.map(c=>'<option>'+c+'</option>').join('')+'</select></label><label class="field">Количество<input data-part-quantity type="number" min="0" step="1" required></label><label class="field">Цена / шт.<input data-part-price type="number" min="0" step="0.01" placeholder="Рынок"></label><p class="city-part-quote hint"></p><div class="city-part-actions"><button type="button" class="button" data-part-rest>Остаток сюда</button><button type="button" class="button" data-part-remove>Удалить</button></div>';
 node.querySelector('select').value=row.city;node.querySelector('[data-part-quantity]').value=row.quantity;node.querySelector('[data-part-price]').value=row.price??'';node.querySelector('[data-part-remove]').onclick=()=>{node.remove();totals();};node.querySelector('[data-part-rest]').onclick=()=>{const others=rowsFromDialog().reduce((n,r)=>n+(Number.isFinite(r.quantity)?r.quantity:0),0)-(node.querySelector('[data-part-quantity]').valueAsNumber||0);node.querySelector('[data-part-quantity]').value=Math.max(0,session.required-others);totals();};
 function marketHint(){const q=currentQuote(node.querySelector('select').value);node.querySelector('.city-part-quote').textContent=q.price>0?'Рынок: '+fmt(q.price)+' / шт. · '+(node.querySelector('[data-part-price]').value===''?'используется рыночная цена':'используется ручная цена'):'Нет проверенной цены рынка — укажите свою.';}
 node.querySelector('select').onchange=()=>{node.querySelector('[data-part-price]').value='';marketHint();totals();};node.oninput=()=>{marketHint();totals();};$('city-allocation-rows').append(node);marketHint();totals();return node;
}
function open(kind,id){if(dialog.open)return;const x=A.snapshot(),m=x.result.bill.find(m=>m.id===id);if(kind==='buy'&&!m)return;
 session={kind,id,required:kind==='sale'?x.result.amount:m.buy,allowed:kind==='sale'?allowed(x):M.cities,identity:identity(),focus:document.activeElement,key:kind==='buy'?M.key(id,m,x.config.quality):null};
 const existing=kind==='sale'?x.result.sales?.demand?x.result.sales.rows.map(r=>({city:r.city,quantity:r.quantity,price:null})):x.config.saleSplits:x.config.purchaseSplits?.[session.key];
 const initial=existing||[{city:kind==='sale'?x.config.sellCity:m.city,quantity:session.required,price:kind==='sale'?x.config.manualSale?x.config.salePrice:null:m.manual?m.price:null}];
 dialog.innerHTML='<form><div class="city-allocation-heading"><h2 id="city-allocation-title"></h2><button class="button" id="city-allocation-close" type="button" aria-label="Закрыть">×</button></div><p id="city-allocation-item"></p><p class="hint">Укажите количество для каждого города. Пустая цена берётся с рынка. При смене города цена сбрасывается. Возврат и запас уже учтены в требуемом количестве.</p><div id="city-allocation-rows"></div><button type="button" class="button" id="city-allocation-add">+ Добавить город</button><p role="status" id="city-allocation-status"></p><div class="city-allocation-actions"><button class="button primary" type="submit">Применить</button><button type="button" class="button" id="city-allocation-cancel">Отмена</button><button type="button" class="button" id="city-allocation-single">Убрать распределение</button></div></form>';
 $('city-allocation-title').textContent=kind==='sale'?'Продажа по городам':'Закупка по городам';$('city-allocation-item').textContent=(kind==='sale'?x.recipe.name:ALBION_DATA.names[id]||id)+' · '+fmt(session.required)+' шт.';initial.forEach(append);
 $('city-allocation-close').onclick=close;$('city-allocation-cancel').onclick=close;$('city-allocation-add').onclick=()=>{const used=rowsFromDialog().map(r=>r.city),city=session.allowed.find(c=>!used.includes(c));if(!city)return;const assigned=rowsFromDialog().reduce((n,r)=>n+(r.quantity||0),0);append({city,quantity:Math.max(0,session.required-assigned),price:null}).querySelector('select').focus();};
 function apply(remove=false){if(session.identity!==identity()){close();return;}const old=A.snapshot().config,patch=session.kind==='sale'?{saleAllocationMode:remove?'single':'manual',saleSplits:remove?null:rowsFromDialog()}:{purchaseSplits:{...old.purchaseSplits,[session.key]:remove?undefined:rowsFromDialog()}};A.setCityAllocation(patch);Workspace.capture();close();}
 $('city-allocation-single').onclick=()=>apply(true);dialog.querySelector('form').onsubmit=e=>{e.preventDefault();if(dialog.querySelector('form').reportValidity())apply();};dialog.showModal();dialog.querySelector('select').focus();
}
dialog.addEventListener('cancel',e=>{e.preventDefault();close();});document.addEventListener('workspacechange',()=>{if(session&&session.identity!==identity())close();});
function demandSettings(x){return x.config.saleDemand||{days:3,share:10,cities:[x.config.sellCity]};}
$('city-sale-mode').onchange=()=>{const x=A.snapshot(),mode=$('city-sale-mode').value;if(mode==='manual'&&(!x.config.saleSplits||x.result.sales?.demand)){open('sale');$('city-sale-mode').value=x.result.sales?.demand?'demand':'single';return;}A.setCityAllocation({saleAllocationMode:mode,saleSplits:mode==='single'?null:x.config.saleSplits,saleDemand:demandSettings(x)});Workspace.capture();};
function saveDemand(){const x=A.snapshot(),next={volume:$('city-demand-volume').value,days:$('city-demand-days').valueAsNumber,share:$('city-demand-share').valueAsNumber,cities:[...$('city-demand-cities input:checked')].map(n=>n.value)};if(!Number.isFinite(next.days)||!Number.isFinite(next.share))return;A.setCityAllocation({saleDemand:next});Workspace.capture();}
$('city-demand-volume').onchange=saveDemand;$('city-demand-days').onchange=saveDemand;$('city-demand-share').onchange=saveDemand;$('city-demand-cities').onchange=saveDemand;
$('city-sales-edit').onclick=()=>open('sale');
function paint(){const x=A.snapshot(),r=x.result,c=x.config,mode=r.sales?.demand?'demand':r.sales?'manual':'single';
 $('city-sale-mode').value=mode;$('city-demand-controls').hidden=mode!=='demand';$('city-sales-edit').hidden=mode==='single';$('city-sales-edit').textContent=mode==='demand'?'Изменить вручную':'Изменить распределение';
 $('sell-city').disabled=mode!=='single';$('sell-city').closest('label').hidden=mode!=='single';$('sell-city').closest('.grid2')?.classList.toggle('city-multiple-sale',mode!=='single');const saleLabel=$('sale-price').closest('label').firstChild;if(saleLabel?.nodeType===Node.TEXT_NODE)saleLabel.textContent=mode==='single'?'Цена продажи за штуку, серебро':'Средняя цена продажи за штуку, серебро';$('sale-price').readOnly=mode!=='single';$('sale-price').title=mode==='single'?'':'Средняя цена распределения по городам';
 const settings=demandSettings(x);$('city-demand-volume').value=settings.volume||'batch';if(r.marketVolume){$('quantity').value=r.amount;$('quantity').disabled=true;$('volume-mode').disabled=true;$('focus-budget').closest('label').hidden=true;}
 $('city-demand-days').value=settings.days;$('city-demand-share').value=settings.share;
 const cityList=JSON.stringify(allowed(x)),fieldset=$('city-demand-cities');if(fieldset.dataset.cities!==cityList){fieldset.innerHTML='<legend>Города продажи</legend>'+allowed(x).map(city=>'<label><input type="checkbox" value="'+city+'"> '+city+'</label>').join('');fieldset.dataset.cities=cityList;}for(const input of fieldset.querySelectorAll('input'))input.checked=Array.isArray(settings.cities)&&settings.cities.includes(input.value);
 $('city-sales-plan').innerHTML=r.sales?'<p class="'+(r.sales.valid?'hint':'negative')+'">'+(r.sales.valid?'Распределено '+fmt(r.sales.assigned)+' шт.':esc(r.sales.errors.join(' ')))+'</p><div class="city-plan-list">'+r.sales.rows.map(part=>'<div><b>'+esc(part.city)+'</b><span>'+fmt(part.quantity)+' шт. × '+fmt(part.price)+'</span><strong>'+fmt(part.cost)+'</strong><small>Затраты: '+fmt(part.allocatedCost)+' · Прибыль: '+(part.profit===null?'—':fmt(part.profit))+'</small>'+(r.sales.demand?'<small>'+(!part.historyValid?'Нет свежего объёма рынка':fmt(part.daily)+' шт. / день · лимит '+fmt(part.capacity)+' шт.')+'</small>':'')+'</div>').join('')+'</div><p class="hint">Затраты и побочный доход партии распределены пропорционально количеству. Перевозка включена из общих расходов.</p>':'';
 for(const row of $('materials').querySelectorAll('[data-purchase-id]')){row.querySelector('.city-split-link')?.remove();const id=row.dataset.purchaseId,m=r.bill.find(m=>m.id===id),button=document.createElement('button');button.type='button';button.className='city-split-link';button.dataset.citySplit=id;button.textContent=m.allocation?'По городам: '+m.allocation.rows.filter(p=>p.quantity>0).length+' · изменить':'Разделить по городам';button.onclick=()=>open('buy',id);row.querySelector('.purchase-resource').append(button);if(m.allocation)row.querySelector('[data-city]')?.closest('label').setAttribute('hidden','');}
 const grouped=new Map();function cityRow(city){if(!grouped.has(city))grouped.set(city,{buy:0,sell:0,items:[]});return grouped.get(city);}
 for(const m of r.bill)for(const part of m.allocation?.rows||[{city:m.city,quantity:m.buy,cost:m.cost}])if(part.quantity>0){const g=cityRow(part.city);g.buy+=part.cost;g.items.push((ALBION_DATA.names[m.id]||m.id)+': '+fmt(part.quantity)+' шт.');}
 for(const part of r.sales?.rows||[{city:c.sellCity,quantity:r.amount,cost:r.amount*c.salePrice}])if(part.quantity>0)cityRow(part.city).sell+=part.cost*(c.saleMode==='discord'?1-c.discount/100:1);
 summary.querySelector('div').innerHTML=[...grouped].map(([city,g])=>'<section><h4>'+esc(city)+'</h4><p>Закупка: <b>'+fmt(g.buy)+'</b> · Продажа до удержаний: <b>'+fmt(g.sell)+'</b></p><p class="hint">'+esc(g.items.join(' · '))+'</p></section>').join('')+'<p class="hint">Суммы включены в общую экономику партии. Перевозка задаётся отдельно в расходах.</p>';
 if(r.sales){$('liquidity-content').innerHTML=r.sales.rows.map(part=>{const q=A.allocationSaleQuote(part.city);return '<div class="liq-row"><span>'+esc(part.city)+'</span><strong>'+ (q.historyValid?fmt(q.daily)+' шт. / день':'Нет свежей истории')+'</strong></div>';}).join('')+'<p class="hint">Средний оборот всего рынка. Срок продажи вашей партии не гарантирован.</p>';}
}
document.addEventListener('craftresultchange',paint);paint();window.CityAllocationUI={open,paint};
})();
